/* ============================================================
   Texts in the learner's language (fr) for data/core/grammar-reference.js
   Keys map to the ids of the neutral layer; arrays join by index, so
   their length must match core. Checked by scripts/parity.mjs.

   The contrastive notes are written against French, not translated
   from another language: the point of comparison changes with the
   reader's language. Cells in the learned language (German) carry the
   historical class 'it' in the tables.
   ============================================================ */
LINGUAI.addStrings("fr", {
  "refsec:titles": [
    "Noms et articles",
    "Adjectif et adverbe",
    "Pronoms",
    "Le verbe",
    "Prépositions",
    "La phrase",
    "Prononciation et registre"
  ],
  "ref:g-genus": {
    title: "Le genre du nom",
    sub: "der, die, das ; -ung, -heit, -chen…",
    body: "<p>L'allemand a <b>trois genres</b> : masculin (<em>der</em>), féminin (<em>die</em>) et neutre (<em>das</em>). Le français n'en a que deux, et le genre allemand ne suit pas toujours le vôtre, il le contredit même souvent (parfois il coïncide : <em>la lampe, die Lampe</em>) : <em>le soleil</em> mais <em>die Sonne</em> (féminin), <em>la lune</em> mais <em>der Mond</em> (masculin), <em>la table</em> mais <em>der Tisch</em> (masculin). Ne traduisez donc jamais le genre : apprenez chaque nom <b>avec son article</b>, comme un seul bloc : <em>der Tisch, die Lampe, das Buch</em>.</p><h4>Indices utiles</h4><ul><li><b>die</b> : les noms en <em>-ung, -heit, -keit, -schaft, -ion, -tät</em> (<em>die Zeitung, die Freiheit, die Möglichkeit, die Freundschaft, die Nation, die Universität</em>) et les féminins de personnes en <em>-in</em> (<em>die Lehrerin</em>).</li><li><b>das</b> : les diminutifs en <em>-chen, -lein</em> (<em>das Mädchen, das Kätzchen</em>).</li><li><b>der</b> : en général les noms désignant spécifiquement des hommes (<em>der Vater, der Lehrer</em> ; mais <em>das Kind</em> et <em>das Baby</em> sont neutres, même pour un garçon).</li></ul><p class='callout callout--trap'>Le neutre n'est pas la catégorie « des choses » : <em>der Tisch</em> et <em>der Kaffee</em> sont masculins. Et <em>das Mädchen</em> (la fille) est neutre à cause de <em>-chen</em>, pas féminin.</p>"
  },
  "ref:g-plural": {
    title: "Le pluriel",
    sub: "-e, -er, -(e)n, -s, sans terminaison, tréma",
    body: "<p>En français, le pluriel s'écrit surtout avec un <em>-s</em> muet : à l'oral, seul l'article change (<em>le livre, les livres</em>). En allemand, le pluriel modifie souvent la forme et la prononciation du nom (certains noms restent pourtant identiques : <em>der Lehrer → die Lehrer</em>), et il existe <b>cinq schémas</b>. On ne les devine pas à coup sûr : apprenez le pluriel avec le nom (le dictionnaire le donne : <em>Tag, -e</em>).</p><div class='table-wrap'><table class='gt'><thead><tr><th>schéma</th><th>singulier</th><th>pluriel</th></tr></thead><tbody><tr><td>-e (souvent avec tréma)</td><td class='it'>der Tag, der Stuhl</td><td class='it'>die Tage, die Stühle</td></tr><tr><td>-er (tréma si possible)</td><td class='it'>das Kind, das Haus</td><td class='it'>die Kinder, die Häuser</td></tr><tr><td>-(e)n</td><td class='it'>die Frau, die Lampe</td><td class='it'>die Frauen, die Lampen</td></tr><tr><td>-s</td><td class='it'>das Auto</td><td class='it'>die Autos</td></tr><tr><td>sans terminaison</td><td class='it'>der Lehrer, der Bruder</td><td class='it'>die Lehrer, die Brüder</td></tr></tbody></table></div><ul><li><b>Tréma</b> : <em>a → ä, o → ö, u → ü, au → äu</em> (<em>der Apfel → die Äpfel</em>).</li><li>Au pluriel, l'article est <b>die</b> au nominatif et à l'accusatif, quel que soit le genre (au datif ce sera <em>den</em>, plus tard).</li><li>Les féminins en <em>-in</em> doublent le n : <em>die Lehrerin → die Lehrerinnen</em>.</li><li>La plupart des féminins prennent <em>-(e)n</em> ; le <em>-s</em> est rare, surtout pour des mots empruntés.</li></ul>"
  },
  "ref:g-artikel-nom": {
    title: "Les articles au nominatif",
    sub: "der, die, das, die ; ein, eine, ein ; kein",
    body: "<p>Le <b>nominatif</b> est le cas du sujet, et du groupe nominal attribut après <em>sein</em> : <em>Der Tisch ist neu. Das ist ein Tisch.</em> (L'adjectif attribut, <em>neu</em>, reste invariable.) C'est la forme du dictionnaire. Attention : <em>Ich bin in der Schule</em> n'est pas un attribut, c'est un groupe prépositionnel, <em>der</em> n'y est donc pas un nominatif.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>masc.</th><th>fém.</th><th>neutre</th><th>pluriel</th></tr></thead><tbody><tr><td>défini</td><td class='it'>der</td><td class='it'>die</td><td class='it'>das</td><td class='it'>die</td></tr><tr><td>indéfini</td><td class='it'>ein</td><td class='it'>eine</td><td class='it'>ein</td><td class='it'>(pas d'article)</td></tr><tr><td>négatif</td><td class='it'>kein</td><td class='it'>keine</td><td class='it'>kein</td><td class='it'>keine</td></tr></tbody></table></div><ul><li><em>ein</em> et <em>kein</em> n'ont pas de terminaison au masculin et au neutre ; le féminin prend <em>-e</em>.</li><li>Le pluriel indéfini n'existe pas : là où le français dit <em>des livres</em>, l'allemand n'a rien : <em>Das sind Bücher</em>. Même chose pour le partitif : <em>Ich trinke Kaffee</em> (je bois du café).</li><li>Pas d'élision : <em>der Apfel, die Orange</em>, jamais « l'Apfel ».</li></ul><p class='callout callout--trap'>Ne choisissez pas l'article d'après le français : <em>das Mädchen</em>, <em>der Mond</em>. Le genre, on l'apprend avec le mot.</p>"
  },
  "ref:g-artikel-akk": {
    title: "Les articles à l'accusatif",
    sub: "den, einen, keinen : seul le masculin change",
    body: "<p>L'<b>accusatif</b> marque le complément d'objet direct : <em>Ich nehme einen Kaffee. Ich sehe den Mann.</em> En français, ni le nom ni l'article ne changent selon la fonction (seuls les pronoms : <em>il, le</em>). En allemand, c'est l'article qui porte le cas, le nom reste en général identique (exception : quelques masculins dits faibles, <em>der Student → den Studenten, der Junge → den Jungen</em>).</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>masc.</th><th>fém.</th><th>neutre</th><th>pluriel</th></tr></thead><tbody><tr><td>nominatif</td><td class='it'>der / ein / kein</td><td class='it'>die / eine / keine</td><td class='it'>das / ein / kein</td><td class='it'>die / – / keine</td></tr><tr><td>accusatif</td><td class='it'><b>den / einen / keinen</b></td><td class='it'>die / eine / keine</td><td class='it'>das / ein / kein</td><td class='it'>die / – / keine</td></tr></tbody></table></div><p>Seul le <b>masculin singulier</b> change : <em>der Kaffee → den Kaffee</em>. Le féminin, le neutre et le pluriel sont identiques au nominatif :</p><ul><li><em>Ich habe einen Bruder.</em> mais <em>Ich habe eine Schwester.</em></li><li><em>Ich sehe das Auto. Ich brauche keinen Stift.</em></li><li>Au café : <em>Einen Kaffee, bitte.</em> (Un café, s'il vous plaît.)</li></ul><p class='callout callout--trap'>Les verbes <em>haben, nehmen, sehen, brauchen, trinken</em> sont suivis de l'accusatif. Penser au sujet et à l'objet : le masculin du sujet est <em>der</em>, celui de l'objet est <em>den</em>.</p>"
  },
  "ref:g-artikel-dat": {
    title: "L'article au datif",
    sub: "dem, der, dem, den + -n ; einem, einer ; meinem",
    body: "<p>Le datif est le cas qu'on emploie après certaines prépositions (<em>mit, zu, bei, aus, von, nach, seit</em>) et pour dire <em>où</em> se trouve quelque chose, mais seulement avec une préposition à double cas (<em>in, an, auf</em>…) : <em>in der Küche</em> ; les autres prépositions régissent leur propre cas. Contrairement à l'accusatif, <b>tous les genres changent</b>.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>masc.</th><th>fém.</th><th>neutre</th><th>pluriel</th></tr></thead><tbody><tr><td>défini</td><td class='it'>dem</td><td class='it'>der</td><td class='it'>dem</td><td class='it'>den + <b>-n</b></td></tr><tr><td>indéfini</td><td class='it'>einem</td><td class='it'>einer</td><td class='it'>einem</td><td>(aucun)</td></tr><tr><td>négatif</td><td class='it'>keinem</td><td class='it'>keiner</td><td class='it'>keinem</td><td class='it'>keinen + <b>-n</b></td></tr><tr><td>possessif (mein)</td><td class='it'>meinem</td><td class='it'>meiner</td><td class='it'>meinem</td><td class='it'>meinen + <b>-n</b></td></tr></tbody></table></div><p>Exemples : <em>Ich fahre mit dem Bus. Ich wohne bei meiner Schwester. Er kommt aus der Stadt.</em></p><p>Au pluriel, le datif ajoute <b>-n</b> au nom, sauf si le pluriel se termine déjà par <em>-n</em> ou <em>-s</em> : <em>die Kinder → mit den Kindern</em>, <em>die Freunde → mit den Freunden</em>, mais <em>die Frauen → mit den Frauen</em> et <em>die Autos → mit den Autos</em>.</p><p class='callout callout--trap'>En français, la préposition ne change rien à l'article : <em>avec la femme, chez le médecin</em>. L'article varie seulement selon le genre et le nombre (et se contracte : <em>au, du</em>). En allemand, la préposition <b>demande un cas</b> et c'est l'article qui le montre : <em>mit der Frau</em>, et non <s>mit die Frau</s>. Apprends chaque préposition avec son cas (<em>mit + Dativ</em>).</p><p>Les prépositions suivies du datif ont leur propre fiche ; pour l'instant, il suffit de reconnaître la forme et de ne pas employer <em>den</em> au masculin singulier après <em>mit</em> : <em>mit dem Mann</em>.</p>"
  },
  "ref:g-adjektivdeklination": {
    title: "L'adjectif attribut",
    sub: "Der Pullover ist rot : aucune terminaison",
    body: "<p>Quand l'adjectif suit <em>sein</em> (ou <em>werden, bleiben</em>), il reste <b>invariable</b> : il ne s'accorde pas avec le nom en genre et en nombre.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>phrase</th></tr></thead><tbody><tr><td>masculin</td><td class='it'>Der Pullover ist rot.</td></tr><tr><td>féminin</td><td class='it'>Die Jacke ist rot.</td></tr><tr><td>neutre</td><td class='it'>Das Hemd ist rot.</td></tr><tr><td>pluriel</td><td class='it'>Die Schuhe sind rot.</td></tr></tbody></table></div><p>Autres exemples : <em>Der Mantel ist teuer. Sie ist nett. Das Zimmer ist klein. Mein Bruder ist unfreundlich.</em> Aussi avec <em>aussehen</em> : <em>Wie sieht er aus? Er sieht müde aus.</em></p><p class='callout callout--trap'>Le français accorde l'adjectif attribut (<em>il est grand, elle est grande, ils sont grands, elles sont grandes</em>) ; l'allemand attribut ne change <b>jamais</b> : <em>Die Schuhe sind rot</em>, pas <s>roten</s> ni <s>rote</s>. Quand l'adjectif se place <b>devant le nom</b> (<em>ein roter Pullover</em>), les terminaisons apparaissent, mais elles viennent aux niveaux suivants : pour l'instant, n'emploie l'adjectif qu'après <em>sein</em>.</p><p>Pour demander comment est quelque chose : <em>Wie ist der Pullover?</em> Pour les couleurs et les autres adjectifs de base, voir le vocabulaire des unités 4 et 8.</p>"
  },
  "ref:g-komparation": {
    title: "Comparatif et superlatif",
    sub: "-er ... als, so ... wie, am -sten",
    body: "<p>Le comparatif de supériorité se forme avec <b>-er</b>, le superlatif attribut avec <b>am ... -sten</b>. Pour comparer on emploie <b>als</b> (supériorité et infériorité ; l'infériorité se dit <b>weniger ... als</b>, <em>weniger schön als</em>, sans <b>-er</b>), pour l'égalité <b>so ... wie</b>.</p><div class='table-wrap'><table class='gt'><thead><tr><th>base</th><th>comparatif</th><th>superlatif</th></tr></thead><tbody><tr><td class='it'>klein</td><td class='it'>kleiner</td><td class='it'>am kleinsten</td></tr><tr><td class='it'>schnell</td><td class='it'>schneller</td><td class='it'>am schnellsten</td></tr><tr><td class='it'>alt</td><td class='it'>älter</td><td class='it'>am ältesten</td></tr><tr><td class='it'>jung</td><td class='it'>jünger</td><td class='it'>am jüngsten</td></tr><tr><td class='it'>groß</td><td class='it'>größer</td><td class='it'>am größten</td></tr><tr><td class='it'>gut</td><td class='it'>besser</td><td class='it'>am besten</td></tr><tr><td class='it'>viel</td><td class='it'>mehr</td><td class='it'>am meisten</td></tr><tr><td class='it'>gern</td><td class='it'>lieber</td><td class='it'>am liebsten</td></tr></tbody></table></div><p>Exemples : <em>Er ist größer als du. Sie ist so groß wie ich. Anna ist am größten. Ich trinke lieber Tee als Kaffee. Am liebsten trinke ich Wasser.</em></p><p>Beaucoup d'adjectifs courts prennent l'<b>Umlaut</b> (<em>alt, jung, groß</em>) ; <em>gut, viel, gern</em> ont des formes propres à apprendre par cœur, comme <em>bon → meilleur</em> en français.</p><p class='callout callout--trap'>Le français dit <em>que</em> dans les deux cas (<em>plus grand que toi, aussi grand que toi</em>) ; l'allemand sépare : <b>als</b> pour <em>plus ... que</em> (<em>größer als du</em>) et <b>wie</b> pour l'égalité (<em>so groß wie du</em>). Ne mets pas <em>wie</em> après un comparatif. De plus, le français ajoute <em>le</em> au superlatif (<em>le plus grand</em>) ; ici, quand il se rapporte au sujet de la phrase, on dit <em>Er ist am größten</em>.</p><p>On ne voit ici que le comparatif en position d'attribut ; devant le nom (<em>der größere Bruder</em>), il viendra avec les terminaisons de l'adjectif.</p>"
  },
  "ref:g-possessiv": {
    title: "Les possessifs",
    sub: "mein, dein, sein, ihr, unser, euer, Ihr",
    body: "<p>Le possessif se choisit d'après le <b>possesseur</b>, puis il prend les terminaisons de <em>ein</em> selon le genre et le cas du <b>nom possédé</b>.</p><div class='table-wrap'><table class='gt'><thead><tr><th>possesseur</th><th>possessif</th></tr></thead><tbody><tr><td class='it'>ich</td><td class='it'>mein</td></tr><tr><td class='it'>du</td><td class='it'>dein</td></tr><tr><td class='it'>er</td><td class='it'>sein</td></tr><tr><td class='it'>sie (elle)</td><td class='it'>ihr</td></tr><tr><td class='it'>es</td><td class='it'>sein</td></tr><tr><td class='it'>wir</td><td class='it'>unser</td></tr><tr><td class='it'>ihr</td><td class='it'>euer</td></tr><tr><td class='it'>sie (ils, elles)</td><td class='it'>ihr</td></tr><tr><td class='it'>Sie (politesse)</td><td class='it'>Ihr</td></tr></tbody></table></div><p>Exemples : <em>Meine Mutter heißt Anna. Mein Chef ist nett. Das ist unser Haus. Ich sehe meinen Bruder.</em> Au féminin et au pluriel, au nominatif et à l'accusatif : <em>mein</em> + <b>-e</b> (<em>meine Mutter, meine Eltern</em>) ; à l'accusatif masculin <em>meinen</em> ; au datif <em>meiner Mutter, meinen Eltern</em>. <em>euer</em> perd son <em>e</em> devant une terminaison : <em>eure Mutter, euren Bruder</em>.</p><p>Avec les prénoms, le génitif se forme avec <b>-s</b> et sans apostrophe : <em>Annas Mutter, Peters Auto</em>. Si le nom finit par une sifflante (<em>-s, -x, -z, -ß</em>), on met seulement l’apostrophe : <em>Hans’ Mutter, Max’ Auto</em>. Le complément se place devant le nom, alors que le français passe par <em>de</em> (<em>la mère d'Anna</em>).</p><p class='callout callout--trap'>Le français accorde le possessif avec le nom possédé (<em>son père, sa mère, ses parents</em>) : <em>sa mère</em> peut être celle de lui ou celle d'elle. En allemand, le possesseur s'entend : <em>seine Mutter</em> est la mère de lui, <em>ihre Mutter</em> celle d'elle. Comme en français, le possessif <b>n'a pas d'article</b> devant lui : <em>mon livre</em> se dit <em>mein Buch</em>.</p><p>La forme de politesse <em>Ihr</em> s'écrit avec une majuscule, comme <em>Sie</em> : <em>Wie ist Ihr Name?</em></p>"
  },
  "ref:g-adverbien": {
    title: "Les adverbes",
    sub: "sehr, zu, viel, wenig ; immer, oft, manchmal, nie ; gut",
    body: "<h4>Degré</h4><ul><li><b>sehr</b> (très) devant l'adjectif : <em>Der Kaffee ist sehr gut.</em></li><li><b>zu</b> (trop) : <em>Die Hose ist zu klein.</em> <b>ziemlich</b> (assez), <b>ein bisschen</b> (un peu).</li><li><b>viel</b> et <b>wenig</b> après le verbe : <em>Ich arbeite viel. Er schläft wenig.</em></li></ul><h4>Fréquence</h4><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>sens</th></tr></thead><tbody><tr><td class='it'>immer</td><td>toujours</td></tr><tr><td class='it'>oft</td><td>souvent</td></tr><tr><td class='it'>manchmal</td><td>parfois</td></tr><tr><td class='it'>selten</td><td>rarement</td></tr><tr><td class='it'>nie</td><td>jamais</td></tr></tbody></table></div><p>En général, ils se placent après le verbe : <em>Ich trinke immer Kaffee.</em> S'ils ouvrent la phrase, le sujet passe après le verbe : <em>Morgens trinke ich immer Kaffee.</em></p><h4>Manière</h4><p>L'adjectif, sans terminaison, fait aussi fonction d'adverbe : <em>Er spricht gut. Sie fährt schnell. Das Kind schläft ruhig.</em> <em>gern</em> (volontiers) est lui aussi un adverbe : <em>Ich lese gern.</em></p><p class='callout callout--trap'>Le français distingue <em>bon</em> et <em>bien</em>, <em>rapide</em> et <em>rapidement</em> ; l'allemand emploie le même mot : <em>Der Kaffee ist gut</em> (il est bon) et <em>Er spricht gut</em> (il parle bien). Pour <em>très</em> et <em>beaucoup</em>, la répartition est proche de la nôtre : <b>sehr</b> avec un adjectif ou un adverbe (<em>sehr gut</em>), <b>viel</b> pour la quantité (<em>viel Zeit, Ich schlafe viel</em>) ; <s>viel gut</s> est faux. Attention à <em>nie</em> : il contient déjà la négation, donc pas de <em>nicht</em>, et rien ne correspond au <em>ne</em> de <em>ne ... jamais</em> : <em>Ich trinke nie Bier</em>.</p>"
  },
  "ref:g-personalpron": {
    title: "Les pronoms personnels sujets",
    sub: "ich, du, er, sie, es, wir, ihr, sie, Sie",
    body: "<div class='table-wrap'><table class='gt'><thead><tr><th>personne</th><th>singulier</th><th>pluriel</th></tr></thead><tbody><tr><td>1</td><td class='it'>ich</td><td class='it'>wir</td></tr><tr><td>2</td><td class='it'>du</td><td class='it'>ihr</td></tr><tr><td>3</td><td class='it'>er / sie / es</td><td class='it'>sie</td></tr><tr><td>politesse</td><td class='it'>Sie</td><td class='it'>Sie</td></tr></tbody></table></div><p>Comme en français, le sujet est normalement exprimé : <em>Ich wohne in Köln</em>, jamais « Wohne in Köln » ; à l'impératif, le pronom manque pour <em>du</em> et <em>ihr</em> (<em>Komm! Kommt!</em>) mais reste pour <em>Sie</em> (<em>Kommen Sie!</em>). Des principales coordonnées peuvent omettre un sujet commun : <em>Ich gehe ins Kino und sehe einen Film.</em></p><h4>Où l'allemand diffère du français</h4><ul><li><b>vous</b> se divise en deux : <em>ihr</em> pour plusieurs amis (pluriel de <em>du</em>), <em>Sie</em> pour la politesse, au singulier comme au pluriel. Le français <em>vous</em> fait les deux tâches à la fois.</li><li><b>sie</b> veut dire trois choses : <em>elle</em> (<em>sie ist</em>), <em>ils / elles</em> (<em>sie sind</em>) et, avec une majuscule, <em>vous</em> de politesse (<em>Sie sind</em>). Seuls le verbe et la majuscule les distinguent. L'allemand n'a pas de <em>ils / elles</em> séparés.</li><li><b>er / sie / es</b> suivent le genre grammatical, pas le sens : <em>der Tisch → er, die Lampe → sie, das Buch → es</em>. Un livre n'est pas « il » mais <em>es</em>.</li><li><em>es</em> sert aussi de sujet vide : <em>Es regnet</em> (il pleut), <em>Wie geht es dir?</em></li></ul>"
  },
  "ref:g-pron-akk": {
    title: "Les pronoms à l'accusatif",
    sub: "mich, dich, ihn, sie, es, uns, euch, sie, Sie",
    body: "<p>Quand le complément d'objet direct est déjà connu, on le remplace par le pronom à l'accusatif. Changent <em>ich, du, er, wir, ihr</em> ; <em>sie, es</em> et <em>sie/Sie</em> restent identiques au nominatif.</p><div class='table-wrap'><table class='gt'><thead><tr><th>nominatif</th><th>accusatif</th></tr></thead><tbody><tr><td class='it'>ich</td><td class='it'>mich</td></tr><tr><td class='it'>du</td><td class='it'>dich</td></tr><tr><td class='it'>er</td><td class='it'>ihn</td></tr><tr><td class='it'>sie</td><td class='it'>sie</td></tr><tr><td class='it'>es</td><td class='it'>es</td></tr><tr><td class='it'>wir</td><td class='it'>uns</td></tr><tr><td class='it'>ihr</td><td class='it'>euch</td></tr><tr><td class='it'>sie</td><td class='it'>sie</td></tr><tr><td class='it'>Sie</td><td class='it'>Sie</td></tr></tbody></table></div><p>Pour les choses, le pronom suit le <b>genre du nom allemand</b>, pas celui du mot français : <em>Was kostet der Pullover? Ich nehme ihn. Wie findest du die Jacke? Ich nehme sie. Das Hemd? Ich nehme es.</em> (<em>la chemise</em> est féminine en français, mais <em>das Hemd</em> est neutre : <em>es</em>.) Avec les personnes : <em>Ich sehe dich. Er ruft uns an. Ich liebe sie.</em></p><p class='callout callout--trap'>En français, le pronom complément se place <b>avant le verbe</b> (<em>je le prends, je te vois</em>). En allemand, le pronom occupe la place du complément : <b>après le verbe</b>, comme un nom, et le verbe reste en deuxième position : <em>Ich nehme ihn</em>, pas <s>Ich ihn nehme</s>. Il n'y a pas non plus de pronom <em>en</em> : <em>j'en prends deux</em> se dit <em>Ich nehme zwei</em>.</p>"
  },
  "ref:g-indefinitpron": {
    title: "einer, eins, welche, keiner",
    sub: "pronoms qui remplacent un nom déjà mentionné",
    body: "<p>Pour ne pas répéter un nom, on emploie des formes de <em>ein</em>, <em>kein</em> et <em>welche</em> sans le nom. La terminaison montre le genre et le cas.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>masc.</th><th>fém.</th><th>neutre</th><th>pluriel</th></tr></thead><tbody><tr><td>nominatif</td><td class='it'>einer</td><td class='it'>eine</td><td class='it'>eins</td><td class='it'>welche</td></tr><tr><td>accusatif</td><td class='it'>einen</td><td class='it'>eine</td><td class='it'>eins</td><td class='it'>welche</td></tr><tr><td>négatif (nom.)</td><td class='it'>keiner</td><td class='it'>keine</td><td class='it'>keins</td><td class='it'>keine</td></tr><tr><td>négatif (acc.)</td><td class='it'>keinen</td><td class='it'>keine</td><td class='it'>keins</td><td class='it'>keine</td></tr></tbody></table></div><p>Exemples : <em>Ich brauche einen Stuhl. Haben Sie einen? Ja, ich habe einen. Haben Sie Brötchen? Ja, wir haben welche. Nein, wir haben keine. Ein Bier? Ich nehme eins.</em></p><p>Avec un nombre, le nombre suffit : <em>Ich nehme zwei.</em> <b>welche</b> remplace un nom pluriel déjà connu : <em>Hast du Brötchen? Ja, ich habe welche.</em> (<em>Tu as des petits pains ? Oui, j'en ai.</em>). Un nom singulier non comptable prend une forme accordée : <em>Hast du Milch? Ja, ich habe welche.</em> (féminin), <em>Hast du Geld? Ja, ich habe welches.</em> (neutre). Le nom sans article reste possible quand on le nomme : <em>Ich kaufe Brötchen.</em></p><p class='callout callout--trap'>Le français résout tout avec <em>en</em> (<em>j'en ai, tu en veux ?</em>), un seul pronom pour les deux genres et les deux nombres. L'allemand n'a pas de pronom équivalent : il emploie un pronom qui s'accorde avec le nom sous-entendu, et <em>welche</em> (et <em>welches</em> au neutre) correspond à <em>en</em> pour un pluriel ou une quantité non précisée : <em>Hast du einen Bruder? Ja, ich habe einen.</em> (<em>Oui, j'en ai un.</em>) Au neutre la forme est <em>eins</em> (à l'écrit aussi <em>eines</em>). Les formes complètes avec <em>jemand, jeder, etwas</em> arrivent en B1.</p>"
  },
  "ref:g-es": {
    title: "es gibt, es regnet, es geht",
    sub: "es sans sens propre",
    body: "<p>Dans beaucoup de phrases allemandes, le sujet <em>es</em> ne désigne pas une chose, mais il est nécessaire : en règle générale, la phrase demande un sujet exprimé.</p><h4>es gibt (il y a)</h4><p>La forme est <b>toujours au singulier</b>, et après <em>gibt</em> le nom se met à l'<b>accusatif</b> : <em>Es gibt einen Bahnhof. Es gibt keinen Supermarkt hier. Es gibt drei Kinos in der Stadt.</em> Question : <em>Gibt es hier ein Café?</em></p><h4>Temps, heure, états</h4><ul><li><em>Es regnet. Es schneit. Es ist kalt. Es ist heiß.</em></li><li><em>Es ist Montag. Wie spät ist es? Es ist acht Uhr.</em></li><li><em>Wie geht's? Es geht.</em></li></ul><p class='callout callout--trap'>Ici le français est proche : il a lui aussi un sujet vide (<em>il pleut, il est tard, il y a</em>), et <em>es</em> ne s'omet pas : <em>Es regnet</em>, pas <s>Regnet</s>. Les pièges sont ailleurs : <em>il fait froid</em> se dit avec <em>sein</em> (<em>Es ist kalt</em>), et après <em>es gibt</em> il faut l'accusatif (<em>einen Bahnhof</em>). <em>es gibt</em> introduit en général quelque chose de nouveau, donc avec <em>ein, kein</em> ou sans article (<em>Es gibt ein Café</em>) ; pour situer une chose déjà connue, on emploie <em>sein</em> (<em>Wo ist das Café? Es ist neben der Post.</em>).</p><p>Les emplois de <em>es</em> comme élément provisoire ou comme renvoi à une subordonnée viennent beaucoup plus tard.</p>"
  },
  "ref:g-praesens": {
    title: "Le présent",
    sub: "-e, -st, -t, -en, -t, -en ; sein, haben ; e → i / ie, a → ä",
    body: "<p>On retire <em>-en</em> de l'infinitif et on ajoute la terminaison. Contrairement au français, où plusieurs terminaisons sont muettes (<em>je parle, tu parles, il parle</em> sonnent pareil), en allemand elles se prononcent toutes et indiquent la personne.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>wohnen</th><th>arbeiten</th><th>essen</th><th>sein</th><th>haben</th></tr></thead><tbody><tr><td>ich</td><td class='it'>wohne</td><td class='it'>arbeite</td><td class='it'>esse</td><td class='it'>bin</td><td class='it'>habe</td></tr><tr><td>du</td><td class='it'>wohnst</td><td class='it'>arbeitest</td><td class='it'>isst</td><td class='it'>bist</td><td class='it'>hast</td></tr><tr><td>er/sie/es</td><td class='it'>wohnt</td><td class='it'>arbeitet</td><td class='it'>isst</td><td class='it'>ist</td><td class='it'>hat</td></tr><tr><td>wir</td><td class='it'>wohnen</td><td class='it'>arbeiten</td><td class='it'>essen</td><td class='it'>sind</td><td class='it'>haben</td></tr><tr><td>ihr</td><td class='it'>wohnt</td><td class='it'>arbeitet</td><td class='it'>esst</td><td class='it'>seid</td><td class='it'>habt</td></tr><tr><td>sie/Sie</td><td class='it'>wohnen</td><td class='it'>arbeiten</td><td class='it'>essen</td><td class='it'>sind</td><td class='it'>haben</td></tr></tbody></table></div><ul><li>Les verbes comme <em>machen</em> suivent le schéma sans exception. Infinitifs en <b>-eln</b> : <em>sammeln → ich sammle, wir sammeln</em> (le <em>-e</em> du radical tombe devant <em>-e</em>, et <em>wir / sie</em> prennent seulement <em>-n</em>). Infinitifs en <b>-ern</b> : <em>wandern → ich wandere, wir wandern</em> (le <em>-e</em> se garde normalement ; une variante <em>ich wandre</em> existe).</li><li>Radical en <b>-t / -d</b> : un <em>-e-</em> s'intercale pour la prononciation : <em>du arbeitest, er arbeitet, ihr arbeitet</em> ; de même <em>finden → du findest</em>. Avec changement de voyelle, c'est autre chose : <em>du hältst, du lädst</em>.</li><li>Radical en <b>-s, -ß, -z</b> : à <em>du</em> la terminaison est <em>-t</em> : <em>du heißt, du tanzt</em>.</li><li><b>Changement de voyelle</b> à <em>du</em> et <em>er/sie/es</em> seulement : <em>essen → du isst</em>, <em>nehmen → nimmt</em>, <em>sprechen → spricht</em>, <em>sehen → sieht</em>, <em>fahren → fährt</em>, et <em>halten → hältst, hält</em>, <em>laden → lädst, lädt</em> (comme <em>je viens, nous venons</em>, mais uniquement à ces deux personnes).</li></ul><p>Le présent allemand couvre aussi « être en train de » : <em>Ich esse</em> = je mange / je suis en train de manger. Pour dire qu'on aime faire quelque chose : <em>gern</em> : <em>Ich esse gern Pizza.</em></p>"
  },
  "ref:g-modalverben": {
    title: "Les verbes modaux",
    sub: "können, wollen, müssen, möchte ; cadre verbal",
    body: "<p>Les modaux expriment la capacité (<em>können</em>), la volonté (<em>wollen</em>), l'obligation (<em>müssen</em>) et le souhait poli (<em>möchte</em>). Ils ont leur propre conjugaison : avec <em>können, wollen, müssen</em>, la 1re et la 3e personne du singulier sont <b>identiques et sans terminaison</b> (<em>ich kann, er kann</em>). <em>möchte</em> fait exception : il a <em>-e</em> (<em>ich möchte, er möchte</em>).</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>können</th><th>wollen</th><th>müssen</th><th>möchten</th></tr></thead><tbody><tr><td>ich</td><td class='it'>kann</td><td class='it'>will</td><td class='it'>muss</td><td class='it'>möchte</td></tr><tr><td>du</td><td class='it'>kannst</td><td class='it'>willst</td><td class='it'>musst</td><td class='it'>möchtest</td></tr><tr><td>er/sie/es</td><td class='it'>kann</td><td class='it'>will</td><td class='it'>muss</td><td class='it'>möchte</td></tr><tr><td>wir</td><td class='it'>können</td><td class='it'>wollen</td><td class='it'>müssen</td><td class='it'>möchten</td></tr><tr><td>ihr</td><td class='it'>könnt</td><td class='it'>wollt</td><td class='it'>müsst</td><td class='it'>möchtet</td></tr><tr><td>sie/Sie</td><td class='it'>können</td><td class='it'>wollen</td><td class='it'>müssen</td><td class='it'>möchten</td></tr></tbody></table></div><p>Le modal est en <b>deuxième position</b>, l'infinitif va <b>à la fin de la phrase</b> : <em>Ich kann heute nicht kommen. Ich muss um sieben aufstehen. Wir wollen am Samstag ins Kino gehen.</em> Le modal et l'infinitif forment un <b>cadre</b> qui enserre le reste de la phrase.</p><p><em>möchte</em> est à l'origine une forme de politesse de <em>mögen</em> (Konjunktiv II) ; à ce niveau, c'est une formule pour les demandes et les souhaits polis, proche de <em>je voudrais</em> : <em>Ich möchte einen Kaffee.</em> (l'infinitif peut être omis). Au restaurant, <em>Ich hätte gern das Schnitzel</em> est aussi une formule figée.</p><p class='callout callout--trap'>En français l'infinitif suit directement le modal (<em>je peux venir aujourd'hui</em>), et le parallèle avec l'allemand s'arrête là : en allemand l'infinitif part à la fin. Même dans une phrase courte (<em>Ich kann heute kommen</em>) il est en dernière position ; avec plusieurs compléments, le cadre se voit mieux : <em>Ich kann heute Abend mit dir ins Kino gehen</em>, et <s>Ich kann gehen heute Abend ins Kino</s> est une erreur. Après le modal, pas de <em>zu</em> devant l'infinitif, comme en français pas de <em>à</em> ni de <em>de</em>. Il existe aussi <em>dürfen</em> et <em>sollen</em>, qui viennent plus tard.</p>"
  },
  "ref:g-trennbare-verben": {
    title: "Les verbes à particule séparable",
    sub: "aufstehen : Ich stehe um sieben auf",
    body: "<p>Beaucoup de verbes ont un préfixe accentué qui, dans la proposition principale, <b>se détache</b> et va à la fin de la phrase. L'infinitif reste uni.</p><div class='table-wrap'><table class='gt'><thead><tr><th>infinitif</th><th>présent</th></tr></thead><tbody><tr><td class='it'>aufstehen</td><td class='it'>Ich stehe um sieben auf.</td></tr><tr><td class='it'>einkaufen</td><td class='it'>Wir kaufen am Samstag ein.</td></tr><tr><td class='it'>anrufen</td><td class='it'>Ich rufe dich an.</td></tr><tr><td class='it'>fernsehen</td><td class='it'>Er sieht abends fern.</td></tr><tr><td class='it'>mitkommen</td><td class='it'>Kommst du mit?</td></tr><tr><td class='it'>ankommen</td><td class='it'>Der Zug kommt um acht an.</td></tr></tbody></table></div><p>Avec un modal, le verbe revient entier, à la fin : <em>Ich muss um sieben aufstehen. Ich möchte heute einkaufen.</em> Les deux parties encadrent la phrase, comme le cadre du modal.</p><p class='callout callout--trap'>Le français n'a pas de préfixe qui se détache : <em>se lever, appeler, acheter</em> restent d'un seul bloc. En allemand, c'est la structure normale : <em>Ich stehe auf</em>, avec <em>auf</em> tout au bout. <em>aufstehen</em> correspond à <em>se lever</em>, qui est pronominal en français : en allemand le verbe <b>ne demande aucun pronom</b> : <em>Ich stehe auf</em>, pas <s>Ich stehe mich auf</s>. Le changement de voyelle reste dans le verbe : <em>fernsehen → er sieht fern</em>, <em>einladen → er lädt ein</em>.</p><p>Préfixes séparables courants : <em>auf-, an-, ein-, mit-, aus-, fern-, zurück-</em>. Ils sont toujours accentués : <em>'aufstehen, 'anrufen</em>.</p><p class='callout callout--trap'>Les préfixes <b>inséparables</b> (<em>be-, ver-, er-, ent-, ge-</em>) ne sont pas accentués et <b>ne se détachent pas</b> : <em>besuchen → Ich besuche dich</em>, <em>verstehen → Ich verstehe das</em>, <em>bekommen → Er bekommt ein Geschenk</em>. Le Partizip II ne prend pas <em>ge-</em> (<em>besucht, verstanden, bekommen</em>). Les préfixes <em>über-, um-, unter-, durch-</em> peuvent être dans les deux cas : on les voit plus tard.</p>"
  },
  "ref:g-imperativ": {
    title: "L'impératif de politesse",
    sub: "Gehen Sie geradeaus !",
    body: "<p>Avec <b>Sie</b>, l'impératif se forme avec l'<b>infinitif + Sie</b> : le verbe est en première position et le pronom vient juste après.</p><div class='table-wrap'><table class='gt'><thead><tr><th>infinitif</th><th>impératif</th></tr></thead><tbody><tr><td class='it'>gehen</td><td class='it'>Gehen Sie geradeaus!</td></tr><tr><td class='it'>nehmen</td><td class='it'>Nehmen Sie die erste Straße links!</td></tr><tr><td class='it'>abbiegen</td><td class='it'>Biegen Sie rechts ab!</td></tr><tr><td class='it'>warten</td><td class='it'>Warten Sie bitte!</td></tr><tr><td class='it'>entschuldigen</td><td class='it'>Entschuldigen Sie, wo ist der Bahnhof?</td></tr></tbody></table></div><p>Les verbes séparables envoient le préfixe à la fin : <em>Biegen Sie rechts ab. Steigen Sie hier aus.</em> Exception : <em>sein</em> donne <b>Seien Sie</b> (<em>Seien Sie bitte pünktlich!</em>), et non <s>Sind Sie</s>. Pour les indications de chemin, il faut aussi <em>geradeaus, links, rechts, die erste, die zweite Straße</em>.</p><p class='callout callout--trap'>En français, l'impératif de politesse se fait avec la forme en <em>-ez</em> et <b>sans pronom</b> (<em>Allez tout droit ! Prenez la première à gauche !</em>). En allemand, le pronom reste, après le verbe : <em>Gehen Sie!</em> Le <em>vous</em> de politesse français correspond à <em>Sie</em> (et jamais à <em>ihr</em>, qui est le pluriel de <em>du</em>). L'impératif a la même forme qu'une question oui/non (verbe en première position suivi de <em>Sie</em>) : <em>Gehen Sie geradeaus!</em> ou <em>Gehen Sie geradeaus?</em> Le français change la forme (<em>Allez-vous tout droit ?</em>), l'allemand non : ce sont le contexte, l'intonation et, à l'écrit, la ponctuation qui les distinguent. Une demande polie peut aussi se terminer par un point, pas seulement par un point d'exclamation.</p><p>Les formes pour <em>du</em> et <em>ihr</em> viennent au niveau suivant.</p>"
  },
  "ref:g-perfekt": {
    title: "Le Perfekt",
    sub: "haben/sein + participe II",
    body: "<p>À l'oral, le passé se fait avec le <b>Perfekt</b> : l'auxiliaire (<em>haben</em> ou <em>sein</em>) en deuxième position et le <b>participe II</b> à la fin de la phrase.</p><p><em>Ich habe gegessen. Wir haben einen Film gesehen. Ich bin nach Berlin gefahren. Sie ist früh aufgestanden.</em></p><div class='table-wrap'><table class='gt'><thead><tr><th>type</th><th>infinitif</th><th>participe II</th></tr></thead><tbody><tr><td>régulier : ge- ... -t</td><td class='it'>machen</td><td class='it'>gemacht</td></tr><tr><td></td><td class='it'>kaufen</td><td class='it'>gekauft</td></tr><tr><td>fort : ge- ... -en</td><td class='it'>essen</td><td class='it'>gegessen</td></tr><tr><td></td><td class='it'>sehen</td><td class='it'>gesehen</td></tr><tr><td>avec sein</td><td class='it'>fahren</td><td class='it'>gefahren</td></tr><tr><td></td><td class='it'>gehen</td><td class='it'>gegangen</td></tr><tr><td></td><td class='it'>kommen</td><td class='it'>gekommen</td></tr><tr><td>séparable : ge- au milieu</td><td class='it'>aufstehen</td><td class='it'>aufgestanden</td></tr><tr><td></td><td class='it'>einkaufen</td><td class='it'>eingekauft</td></tr><tr><td>sans ge-</td><td class='it'>studieren</td><td class='it'>studiert</td></tr><tr><td></td><td class='it'>besuchen</td><td class='it'>besucht</td></tr></tbody></table></div><p>Le participe des verbes forts s'apprend avec l'infinitif (<em>trinken, getrunken ; schreiben, geschrieben</em>). Ne prennent pas <em>ge-</em> les verbes en <em>-ieren</em> et ceux qui ont un préfixe inséparable (<em>be-, ver-, er-</em>).</p><p>On emploie <b>sein</b> avec les verbes intransitifs de <b>changement de lieu ou d'état</b> (<em>fahren, gehen, kommen, fliegen, aufstehen</em>) et avec <em>sein, bleiben, werden, passieren</em> ; avec presque tous les autres, <b>haben</b>. Un verbe de mouvement employé transitivement, avec un COD à l'accusatif, prend <em>haben</em> : <em>Ich habe das Auto gefahren.</em> Un complément au datif ne change pas l'auxiliaire : <em>Ich bin ihm gefolgt.</em> Pour <em>sein</em> et <em>haben</em> eux-mêmes, on préfère <em>war</em> et <em>hatte</em> : <em>Ich war in Berlin.</em></p><p class='callout callout--trap'>Le Perfekt ressemble au passé composé : auxiliaire + participe passé, et c'est le passé de l'oral. Mais le parallèle n'est pas exact. Le choix de l'auxiliaire ne se superpose pas : les verbes pronominaux prennent <em>être</em> en français (<em>je me suis lavé</em>) et <b>haben</b> en allemand (<em>Ich habe mich gewaschen</em>), et la liste des verbes avec <em>sein</em> n'est pas celle des verbes avec <em>être</em> : contrôle le verbe. Et l'accord : le participe allemand <b>ne s'accorde pas</b> avec le sujet (<em>Sie ist gegangen</em>, <em>Wir sind gegangen</em>, alors que le français écrit <em>elle est allée, nous sommes allés</em>).</p>"
  },
  "ref:g-praep-akk": {
    title: "Les prépositions avec l'accusatif",
    sub: "für, ohne, um, durch, gegen",
    body: "<p>Ces prépositions demandent toujours l'<b>accusatif</b> : par conséquent, seul le masculin change (<em>den, einen, keinen, meinen</em>).</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>sens</th><th>exemple</th></tr></thead><tbody><tr><td class='it'>für</td><td>pour</td><td class='it'>Das Geschenk ist für den Lehrer.</td></tr><tr><td class='it'>ohne</td><td>sans</td><td class='it'>Ich trinke Kaffee ohne Zucker.</td></tr><tr><td class='it'>um</td><td>autour de, pour les heures</td><td class='it'>Wir gehen um die Ecke. Um acht Uhr.</td></tr><tr><td class='it'>durch</td><td>à travers</td><td class='it'>Wir gehen durch den Park.</td></tr><tr><td class='it'>gegen</td><td>contre, vers</td><td class='it'>Ich bin gegen den Plan.</td></tr></tbody></table></div><p>Avec les pronoms : <em>für mich, für dich, für ihn, ohne sie, gegen uns</em>. Une formule utile pour la ville : <em>Gehen wir ins Kino?</em> (<em>ins</em> = <em>in das</em> ; l'emploi de <em>in</em> avec le mouvement se voit plus tard).</p><p class='callout callout--trap'>En français, <em>pour Marc</em> ne change rien au nom ni à l'article. En allemand, le cas est marqué par l'article masculin : <em>für den Mann</em>, <em>für einen Freund</em>, et non <s>für der Mann</s>. Avec <em>ohne</em> devant un nom non comptable, on omet en général l'article, comme en français (<em>ohne Zucker, ohne Milch</em> : <em>sans sucre, sans lait</em>).</p>"
  },
  "ref:g-praep-dativ": {
    title: "Les prépositions avec le datif",
    sub: "mit, zu, bei, aus, von, nach, seit",
    body: "<p>Ces sept prépositions demandent toujours le <b>datif</b>.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>sens</th><th>exemple</th></tr></thead><tbody><tr><td class='it'>mit</td><td>avec, moyen de transport</td><td class='it'>Ich fahre mit dem Bus.</td></tr><tr><td class='it'>zu</td><td>vers une personne ou un lieu</td><td class='it'>Ich gehe zum Bahnhof. Wir gehen zur Schule.</td></tr><tr><td class='it'>bei</td><td>chez, auprès de</td><td class='it'>Ich wohne bei meiner Tante. Er ist beim Arzt.</td></tr><tr><td class='it'>aus</td><td>de (provenance)</td><td class='it'>Ich komme aus Italien.</td></tr><tr><td class='it'>von</td><td>de (point de départ)</td><td class='it'>Der Brief ist von meiner Mutter.</td></tr><tr><td class='it'>nach</td><td>destination : vers les villes et les pays sans article ; après</td><td class='it'>Ich fahre nach Berlin. Wir fliegen nach Italien. Nach dem Essen.</td></tr><tr><td class='it'>seit</td><td>depuis (durée ou point de départ, situation qui continue)</td><td class='it'>Ich wohne seit einem Jahr hier. Ich lerne seit Januar Deutsch.</td></tr></tbody></table></div><p>Beaucoup de prépositions fusionnent avec l'article : <b>zu dem → zum</b>, <b>zu der → zur</b>, <b>bei dem → beim</b>, <b>von dem → vom</b>. <em>Gehen Sie zum Bahnhof. Er ist beim Friseur. Ich komme vom Bahnhof.</em></p><p class='callout callout--trap'>Comme en français (<em>à + le → au, de + le → du</em>), l'allemand contracte, mais pas au même endroit : <em>zu der</em> donne <em>zur</em>, alors que <em>à la</em> ne se contracte pas. Les équivalents ne se superposent pas non plus : <em>de</em> se dit <em>aus</em> (provenance : <em>Ich komme aus Rom</em>) ou <em>von</em> (point de départ : <em>vom Bahnhof</em>) ; <em>chez</em> se dit <em>bei</em> (au repos : <em>beim Arzt</em>) ou <em>zu</em> (avec mouvement : <em>zum Arzt</em>) ; <em>depuis</em> + durée ou point de départ (<em>seit Montag, seit Januar, seit 2020</em>) se dit <em>seit</em>, pour une situation qui continue. <em>en autobus</em>, pour nommer le moyen de transport, se dit habituellement <b>mit dem Bus</b> ; <em>im Bus</em> (<em>in dem Bus</em>) n'est pas une faute, mais indique le véhicule dans lequel on se trouve. <em>nach</em> indique la destination : <em>aller à Berlin, en Italie</em> se dit <em>nach Berlin, nach Italien</em>, sans article. Pour le lieu où l'on est, l'allemand dit <em>in</em> : <em>J'habite à Berlin</em> est <em>Ich wohne in Berlin</em>, <em>en Italie</em> est <em>in Italien</em>. Avec les pays qui ont un article, on emploie en revanche <em>in</em> + accusatif (<em>in die Schweiz, in die Türkei, in die USA</em>), contraste à connaître, pas à employer pour l'instant. Formules figées : <em>zu Fuß</em> (à pied), <em>nach Hause</em> (vers la maison), <em>zu Hause</em> (à la maison).</p>"
  },
  "ref:g-wechselpraep": {
    title: "Les prépositions avec datif ou accusatif",
    sub: "wo ? avec le datif : in, an, auf, vor, hinter, neben, ...",
    body: "<p>Neuf prépositions peuvent régir le datif ou l'accusatif. Pour l'instant, on ne voit que la réponse à <b>wo ?</b> (où ? position, lieu où l'on est), qui demande le <b>datif</b>.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>sens</th><th>exemple</th></tr></thead><tbody><tr><td class='it'>in</td><td>dans</td><td class='it'>Ich bin in der Küche. Er wohnt in der Stadt.</td></tr><tr><td class='it'>an</td><td>contre un bord, un mur</td><td class='it'>Das Bild hängt an der Wand. Ich sitze am Fenster.</td></tr><tr><td class='it'>auf</td><td>sur, au contact</td><td class='it'>Das Buch liegt auf dem Tisch.</td></tr><tr><td class='it'>vor</td><td>devant</td><td class='it'>Der Bus hält vor dem Hotel.</td></tr><tr><td class='it'>hinter</td><td>derrière</td><td class='it'>Der Bahnhof ist hinter dem Rathaus.</td></tr><tr><td class='it'>neben</td><td>à côté de</td><td class='it'>Das Café ist neben der Post.</td></tr><tr><td class='it'>über</td><td>au-dessus (sans contact)</td><td class='it'>Die Lampe hängt über dem Tisch.</td></tr><tr><td class='it'>unter</td><td>sous</td><td class='it'>Die Katze schläft unter dem Tisch.</td></tr><tr><td class='it'>zwischen</td><td>entre</td><td class='it'>Das Kino ist zwischen der Bank und dem Park.</td></tr></tbody></table></div><p>Contractions : <b>in dem → im</b>, <b>an dem → am</b> : <em>Ich bin im Park. Wir sind am Bahnhof.</em> Question : <em>Wo ist der Bahnhof? Hinter dem Rathaus.</em></p><p class='callout callout--trap'>Le français emploie des prépositions invariables (<em>dans, sur, sous, devant, derrière, entre</em>) et c'est le verbe qui dit si l'on est immobile ou si l'on va quelque part : <em>je suis dans la cuisine, je vais dans la cuisine</em>. En allemand, c'est le cas qui change le sens : <em>in der Küche</em> (datif) dit où l'on <em>est</em>, tandis que le mouvement vers le lieu (<em>in die Küche</em>, accusatif) arrive en A2. Ici, demande-toi toujours : <em>wo ?</em> alors datif. <em>sur</em> se traduit aussi de deux façons : <em>auf dem Tisch</em> (sur) et <em>an der Wand</em> (accroché au mur).</p>"
  },
  "ref:g-temporalangaben": {
    title: "Heure, jours, mois et dates",
    sub: "um, am, im ; von ... bis, vor, seit",
    body: "<h4>L'heure</h4><p><em>Wie spät ist es?</em> / <em>Wie viel Uhr ist es?</em> Réponse : <em>Es ist acht Uhr.</em> Pour une heure précise : <em>Um acht Uhr.</em></p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>heure</th></tr></thead><tbody><tr><td class='it'>7:00</td><td class='it'>Es ist sieben Uhr.</td></tr><tr><td class='it'>7:15</td><td class='it'>Es ist Viertel nach sieben.</td></tr><tr><td class='it'>7:30</td><td class='it'>Es ist <b>halb acht</b>.</td></tr><tr><td class='it'>7:45</td><td class='it'>Es ist Viertel vor acht.</td></tr><tr><td class='it'>7:10</td><td class='it'>Es ist zehn nach sieben.</td></tr><tr><td class='it'>7:50</td><td class='it'>Es ist zehn vor acht.</td></tr></tbody></table></div><p class='callout callout--trap'><b><em>halb acht</em> veut dire sept heures et demie</b>, pas huit heures et demie : on compte vers l'heure qui vient. Le français dit <em>et demie</em> à partir de l'heure déjà passée : c'est le piège le plus fréquent. En revanche <em>Viertel nach sieben</em> (<em>sept heures et quart</em>) et <em>Viertel vor acht</em> (<em>huit heures moins le quart</em>) se superposent. Comme en français (<em>il est sept heures</em>), on dit <em>es ist</em> au singulier.</p><h4>Prépositions de temps</h4><ul><li><b>um</b> + heure : <em>um acht Uhr</em></li><li><b>am</b> + jour, partie de la journée, date : <em>am Montag, am Abend, am 3. Mai</em> (mais <em>in der Nacht</em>)</li><li><b>im</b> + mois, saison : <em>im Januar, im Sommer</em></li><li><b>von ... bis</b> : <em>von Montag bis Freitag, von acht bis vier</em></li><li><b>vor</b> (il y a) et <b>seit</b> (depuis) + datif : <em>vor einer Woche, seit Montag</em></li></ul><p>Les jours : <em>Montag, Dienstag, Mittwoch, Donnerstag, Freitag, Samstag, Sonntag</em>. Avec <b>-s</b>, on dit que quelque chose arrive chaque fois : <em>montags, morgens, abends</em> (le français : <em>le lundi, le matin, le soir</em>). Les dates se disent avec l'ordinal : <em>am ersten, zweiten, dritten, vierten Mai</em> ; écrites <em>am 1. Mai</em>.</p><p class='callout callout--trap'>Les jours et les mois prennent une <b>majuscule</b> en allemand, pas en français. Pour les dates, le français emploie l'article seul (<em>le 3 mai</em>) et le nombre cardinal (<em>le trois mai</em>) ; l'allemand met <em>am</em> et l'<b>ordinal</b> : <em>am dritten Mai</em>.</p>"
  },
  "ref:g-satz-v2": {
    title: "L'ordre des mots dans la phrase simple",
    sub: "le verbe conjugué en deuxième position",
    body: "<p>Dans une proposition principale déclarative, le <b>verbe conjugué est toujours en deuxième position</b>. La première position peut être n'importe quel élément, et quand ce n'est pas le sujet, le sujet passe après le verbe.</p><ul><li><em>Ich lerne heute Deutsch.</em></li><li><em>Heute lerne ich Deutsch.</em> (inversion)</li><li><em>Montags arbeite ich.</em></li></ul><h4>Questions</h4><ul><li><b>Mot interrogatif</b> en première place, verbe en deuxième : <em>Wo wohnst du? Was isst du? Wann kommst du?</em> L'ordre ressemble à <em>Où habites-tu ?</em>.</li><li><b>Question oui / non</b> : le verbe passe en tête (le verbe en deuxième place vaut pour les déclaratives et les questions à mot interrogatif) : <em>Wohnst du in Berlin? Kommst du heute?</em> Pas d'équivalent de <em>est-ce que</em>.</li></ul><p>En français, l'ordre sujet-verbe est fixe dans la phrase déclarative : <em>Aujourd'hui, j'apprends l'allemand</em>. Le français a l'inversion dans certaines questions (<em>Habites-tu ?</em>), mais pas après un complément de temps. L'allemand, lui, inverse dès que la première place est occupée par autre chose que le sujet.</p><p class='callout callout--trap'>Erreur typique : <em>Heute ich lerne Deutsch.</em> C'est le calque du français. Après <em>heute</em>, le verbe vient avant le sujet : <em>Heute lerne ich Deutsch.</em></p>"
  },
  "ref:g-negation": {
    title: "La négation : nicht et kein",
    sub: "nicht pour le verbe, l'adjectif ; kein pour le nom ; doch",
    body: "<p>Le français encadre le verbe (<em>ne … pas</em>). L'allemand a deux mots simples, selon ce qu'on nie.</p><ul><li><b>kein</b> nie un nom précédé de <em>ein</em> ou sans article. Il s'emploie comme <em>pas de / pas un</em> et se décline comme <em>ein</em> : <em>Ich habe keinen Bruder. Wir haben keine Zeit. Ich trinke keinen Kaffee.</em></li><li><b>nicht</b> nie tout le reste : un verbe, un adjectif, un adverbe, un nom avec l'article défini ou un possessif : <em>Ich arbeite nicht. Das ist nicht gut. Ich kenne den Mann nicht.</em></li></ul><h4>Où placer nicht</h4><ul><li>Dans une phrase simple, <em>nicht</em> se met en général à la <b>fin</b> (tendance, pas règle absolue) : <em>Ich kenne ihn nicht. Er kommt nicht.</em></li><li>Avant un adjectif ou un complément de lieu : <em>Das Buch ist nicht teuer. Ich wohne nicht in Berlin.</em></li></ul><h4>Doch</h4><p>Pour répondre « si » à une question négative, l'allemand a un mot : <em>doch</em>. <em>Du kommst nicht? – Doch!</em> (Si, je viens.) Il ne faut pas répondre <em>ja</em>.</p><p class='callout callout--trap'>Il n'y a pas de <em>ne</em> : <em>Ich nicht arbeite</em> est faux. Et <em>pas de</em> + nom devient <em>kein</em> : <em>Je n'ai pas de frère</em> = <em>Ich habe keinen Bruder</em>.</p>"
  },
  "ref:g-konnektoren": {
    title: "Relier les phrases : und, aber, oder, denn",
    sub: "position zéro : l'ordre ne change pas",
    body: "<p>Ces quatre conjonctions relient deux propositions principales et se placent <b>en position zéro</b> : elles ne comptent pas comme premier élément et chaque proposition garde l'ordre propre à son type : verbe en <b>deuxième position</b> dans une déclarative, en <b>première position</b> dans une question oui/non (<em>Gehen wir ins Kino, oder bleiben wir zu Hause?</em>).</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>sens</th><th>exemple</th></tr></thead><tbody><tr><td class='it'>und</td><td>et</td><td class='it'>Ich gehe ins Kino, und er bleibt zu Hause.</td></tr><tr><td class='it'>aber</td><td>mais</td><td class='it'>Ich bin müde, aber ich gehe ins Kino.</td></tr><tr><td class='it'>oder</td><td>ou</td><td class='it'>Gehen wir ins Kino, oder bleiben wir zu Hause?</td></tr><tr><td class='it'>denn</td><td>car (explique)</td><td class='it'>Ich bleibe zu Hause, denn ich bin müde.</td></tr></tbody></table></div><p>Le sujet reste avant le verbe ; si la deuxième phrase a un autre élément en tête, après la conjonction le verbe garde malgré tout sa position : <em>Ich arbeite, aber am Samstag habe ich frei.</em> Si le sujet est le même, on peut l'omettre après <b>und, oder, aber</b> : <em>Ich gehe ins Kino und sehe einen Film.</em> Pas après <b>denn</b> : le sujet est répété (<em>Ich bleibe zu Hause, denn ich bin müde</em>).</p><p>Avant <b>aber</b> et <b>denn</b>, la virgule est obligatoire ; avant <b>und</b> et <b>oder</b>, elle est facultative entre deux propositions principales.</p><p class='callout callout--trap'><em>parce que</em> se traduit de deux façons. <b>denn</b> est proche de <em>car</em> : il introduit une explication et <b>ne</b> déplace <b>pas</b> le verbe (<em>denn ich bin müde</em>), et, comme <em>car</em>, il ne peut pas ouvrir la phrase. <b>weil</b>, l'équivalent de <em>parce que</em>, envoie le verbe à la fin et arrive en A2. Pour l'instant, pour donner un motif, écris <em>denn</em> et laisse le verbe à sa place.</p>"
  },
  "ref:g-aussprache": {
    title: "Prononciation de base",
    sub: "ä ö ü, ß, ch, sch, sp/st, w, v, z, ei/ie, eu/äu",
    body: "<h4>Voyelles</h4><ul><li><b>ü</b> = le <em>u</em> français (<em>tu</em>) : <em>über, Tür</em>. Bonne nouvelle : vous l'avez déjà. Par contre le <b>u</b> allemand = le <em>ou</em> français : <em>Hut, gut</em>.</li><li><b>ö</b> = <em>eu</em> : <em>schön</em> comme <em>peu</em>, <em>öffnen</em> comme <em>peur</em>. <b>ä</b> = <em>è</em> : <em>Käse</em>.</li><li><b>ei</b> = <em>aï</em> (<em>nein, mein</em>) ; <b>ie</b> = <em>i</em> long (<em>Liebe, Tier</em>) ; <b>eu / äu</b> = <em>oï</em> (<em>Freund, Häuser</em>), pas le <em>eu</em> français.</li><li>Pas de voyelles nasales : dans <em>Anna, Wand, Zimmer</em> le <em>n</em> et le <em>m</em> se prononcent.</li></ul><h4>Consonnes</h4><ul><li><b>ch</b> : après <em>a, o, u, au</em>, un son rauque [x] (<em>Bach, Buch</em>), proche du <em>r</em> français, sans vibrer ; après les autres voyelles et les consonnes, un souffle doux [ç] (<em>ich, Milch</em>), la langue placée comme pour <em>i</em>. Exceptions : <em>chs</em> = [ks] quand le <em>s</em> fait partie du radical (<em>wachsen, sechs, Fuchs</em> ; si le <em>s</em> est une terminaison, <em>ch</em> garde son son : <em>machst, höchste</em>), <em>-ig</em> final = [ɪç] (<em>König</em>), et <em>ch</em> = [k] dans quelques mots d'emprunt (<em>Chor, Charakter</em>).</li><li><b>sch</b> = <em>ch</em> français (<em>Schule</em>) ; <b>sp / st</b> en début de mot = <em>chp / cht</em> (<em>Sport, Stein</em>).</li><li><b>w</b> = <em>v</em> (<em>Wasser</em>) ; <b>v</b> = <em>f</em> dans les mots d'origine allemande (<em>Vater</em>), mais <em>v</em> dans des emprunts (<em>Video, Vase</em>) ; <b>z</b> = <em>ts</em> (<em>Zeit</em>) ; <b>ß</b> = <em>ss</em> sourd (<em>Straße</em>).</li><li><b>h</b> en début de mot se prononce, un léger souffle (<em>Haus</em>) ; le <em>h</em> d'allongement après une voyelle ne se prononce pas (<em>sehen, gehen</em>).</li><li><b>Consonne finale sourde</b> : <em>Tag</em> [taːk], <em>Hund</em> [hʊnt], <em>Bad</em> [baːt] : la consonne s'assourdit, la voyelle longue reste longue.</li></ul><p class='callout callout--trap'>L'accent tonique tombe le plus souvent sur la <b>première syllabe du radical</b> (<em>ARbeiten, WOhnung</em>), pas sur la dernière comme en français. Les préfixes <em>be-, ver-</em> ne portent pas l'accent : <em>beSUchen, verSTEhen</em>.</p>"
  },
  "ref:g-register": {
    title: "Tutoiement, vouvoiement et salutations",
    sub: "du et Sie ; Guten Tag, Tschüss, Auf Wiedersehen",
    body: "<h4>du ou Sie</h4><ul><li><b>du</b> : famille, amis, enfants, étudiants entre eux, et souvent entre collègues.</li><li><b>Sie</b> : inconnus, adultes dans un cadre formel, commerces et administrations, supérieurs. Le verbe est à la 3<sup>e</sup> personne du pluriel : <em>Wie heißen Sie? Woher kommen Sie?</em> Avec <em>Herr</em> ou <em>Frau</em> + nom de famille : <em>Herr Müller, Frau Schmidt</em>.</li></ul><p>L'usage ressemble à <em>tu / vous</em>, mais attention : le français <em>vous</em> sert aussi pour le pluriel ; en allemand, plusieurs amis se disent <em>ihr</em>.</p><h4>Salutations</h4><ul><li><em>Guten Morgen</em> (le matin), <em>Guten Tag</em> (en journée), <em>Guten Abend</em> (le soir), <em>Gute Nacht</em> (avant de dormir ou pour prendre congé tard le soir ; jamais comme salutation d'arrivée).</li><li>Informel : <em>Hallo</em> pour dire bonjour, <em>Tschüss</em> pour dire au revoir. Formel : <em>Auf Wiedersehen</em>. Aussi <em>Bis später, Bis bald</em>.</li></ul><h4>À reconnaître</h4><p><em>Grüß Gott</em> et <em>Servus</em> (Bavière, Autriche : bonjour, et <em>Servus</em> aussi au revoir), <em>Moin</em> (nord de l'Allemagne, à toute heure). Vous les entendrez, vous n'avez pas à les employer.</p>"
  }
});
